/**
 * add-instagram-photos-and-classes-fix.js
 * Run from your project root:   node add-instagram-photos-and-classes-fix.js
 *
 * 1. Replaces the six abstract placeholder tiles in the homepage
 *    "Follow the artistry" section with your five real photos.
 * 2. Classes page heading now reads "Tie it like Gele Glamzzz." (full
 *    name instead of just "Glamzzz").
 *
 * Photos are embedded in this script and written to public/images/
 * automatically. Safe to run more than once.
 */
const fs = require("fs");
const path = require("path");
const root = process.cwd();

function fail(msg) { console.error("✖ " + msg); process.exit(1); }
if (!fs.existsSync(path.join(root, "package.json"))) fail("Run this from your project root.");

const IMAGES = {
  "insta-mint-veil.jpg": "",
  "insta-mint-pose.jpg": "",
  "insta-podcast.jpg": "",
  "insta-glam-gold.jpg": "",
  "insta-glam-white.jpg": "",
};

const imagesDir = path.join(root, "public", "images");
fs.mkdirSync(imagesDir, { recursive: true });
for (const [name, b64] of Object.entries(IMAGES)) {
  fs.writeFileSync(path.join(imagesDir, name), Buffer.from(b64, "base64"));
  console.log("✓ wrote public/images/" + name);
}

function write(rel, content) {
  fs.writeFileSync(path.join(root, rel), content, "utf8");
  console.log("✓ wrote " + rel);
}

write("app/page.js", 'import fs from "fs";\nimport path from "path";\nimport HomeScripts from "@/components/HomeScripts";\nimport { TESTIMONIALS, INSTAGRAM, JOURNAL_MEDIA } from "@/lib/data";\n\nexport const metadata = {\n  title: "Gele Glamzzz: Luxury Gele Artistry in London | The Art of the Crown",\n  description: "Gele Glamzzz is a London based luxury gele artist crafting bridal, ceremonial and editorial headwraps with precision and presence. Discover the artistry and book your experience.",\n};\n\n// Looks for an actual video file instead of requiring an exact hardcoded\n// path. Checks these folders, in order, for the first video file it finds.\n// Called fresh on every page load (see inside HomePage below), never cached.\nfunction findHeroVideo() {\n  const searchDirs = [\n    path.join(process.cwd(), "public", "videos"),\n    path.join(process.cwd(), "public", "images", "videos"),\n    path.join(process.cwd(), "public"),\n  ];\n  const extToType = { ".mp4": "video/mp4", ".webm": "video/webm", ".mov": "video/quicktime" };\n  try {\n    for (const dir of searchDirs) {\n      if (!fs.existsSync(dir)) continue;\n      const match = fs.readdirSync(dir).find((f) => extToType[path.extname(f).toLowerCase()]);\n      if (match) {\n        const relDir = path.relative(path.join(process.cwd(), "public"), dir).split(path.sep).filter(Boolean).join("/");\n        return {\n          src: "/" + (relDir ? relDir + "/" : "") + match,\n          type: extToType[path.extname(match).toLowerCase()],\n        };\n      }\n    }\n  } catch {\n    // if anything goes wrong reading the filesystem, just fall back to no video\n  }\n  return null;\n}\n\n// Same idea as findHeroVideo, but for the small vertical video on the "Ready\n// to be crowned" section. Drop a portrait/vertical .mp4 into\n// public/videos/cta/ and it\'s picked up automatically, no code to touch.\nfunction findCtaVideo() {\n  const dir = path.join(process.cwd(), "public", "videos", "cta");\n  const extToType = { ".mp4": "video/mp4", ".webm": "video/webm", ".mov": "video/quicktime" };\n  try {\n    if (!fs.existsSync(dir)) return null;\n    const match = fs.readdirSync(dir).find((f) => extToType[path.extname(f).toLowerCase()]);\n    if (!match) return null;\n    return { src: "/videos/cta/" + match, type: extToType[path.extname(match).toLowerCase()] };\n  } catch {\n    return null;\n  }\n}\n\nexport default function HomePage() {\n  const heroVideo = findHeroVideo(); // checked fresh on every request, not cached\n  const ctaVideo = findCtaVideo();\n  return (\n    <>\n      {/* ============ Hero ============ */}\n      <section className="hero" id="home">\n        <div className="hero__media">\n          <div className="media-frame__art">\n            <img src="/images/hero-main.jpg" alt="Gele Glamzzz client in an emerald green and gold aso-oke gele and matching wrapper, London" loading="eager" />\n          </div>\n          {/* Drop an .mp4 into /public/videos/ and set the src below — it plays automatically, no other changes needed. */}\n          <video className="hero__video" id="heroVideo" muted loop playsInline preload="metadata" aria-hidden="true">\n            {heroVideo && <source src={heroVideo.src} type={heroVideo.type} />}\n          </video>\n        </div>\n        <div className="hero__scrim" aria-hidden="true"></div>\n        <div className="hero__shutter" id="heroShutter" aria-hidden="true">\n          <span></span><span></span><span></span><span></span><span></span><span></span>\n        </div>\n        <div className="hero__marks" id="heroMarks" aria-hidden="true"><i></i><i></i><i></i><i></i></div>\n        <div className="hero__issue" id="heroIssue"><span>Vol. I, London</span><span>The Art of the Crown</span></div>\n\n        <div className="hero__content">\n          <h1 className="hero__headline reveal-mask">\n            <span className="line line--sm"><span>The</span></span>\n            <span className="line line--lg"><span>Art</span></span>\n            <span className="line line--sm"><span>of the</span></span>\n            <span className="line line--lg"><span>Crown<span className="accent-dot">.</span></span></span>\n          </h1>\n          <div className="hero__foot">\n            <p className="hero__sub">Luxury gele artistry for weddings, ceremonies and unforgettable moments.</p>\n            <div className="hero__ctas">\n              <a href="/booking" className="btn btn--primary" data-cursor="book">Book your experience <span className="btn__arrow">→</span></a>\n              <a href="/about#artistry" className="btn btn--ghost">Discover the artistry <span className="btn__arrow">→</span></a>\n            </div>\n          </div>\n        </div>\n        <div className="hero__scroll"><span>Scroll</span><span className="hero__scroll-line"><span></span></span></div>\n      </section>\n\n      {/* ============ Notable Work: Ayra Starr ============ */}\n      <section className="section-pad on-dark" style={{ background: "var(--void)", color: "var(--ivory)" }}>\n        <div className="container">\n          <div className="story__block">\n            <div className="story__media media-frame" data-reveal-scale>\n              <div className="dissolve">\n                <img src="/images/ayra-starr-stage.jpg" alt="Ayra Starr performing on stage wearing a coral headwrap styled by Gele Glamzzz" loading="lazy" />\n                <img src="/images/final-cta-look.jpg" alt="Ayra Starr in a pink gele styled by Gele Glamzzz" loading="lazy" />\n              </div>\n              <span className="dissolve__credit">Ayra Starr<span>On stage &amp; off, styled by Gele Glamzzz</span></span>\n            </div>\n            <div>\n              <span className="eyebrow" data-reveal>Notable Work</span>\n              <h2 className="h3" data-reveal style={{ marginTop: ".8rem" }}>Styled for<br />the stage.</h2>\n              <p className="body-copy" data-reveal style={{ marginTop: "1.2rem" }}>Ayra Starr doesn&apos;t do quiet entrances. When she needed a headwrap built to hold its shape under stage lights, through a set that never let up, Gele Glamzzz was the call.</p>\n              <p className="pull-quote" data-reveal style={{ marginTop: "1.4rem", fontSize: "var(--fs-md)" }}>&ldquo;Built for the moment. Made to outlast it.&rdquo;</p>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      {/* Featured guest — Fisayo Alonge */}\n      <section className="section-pad on-dark" style={{ background: "var(--void)", color: "var(--ivory)" }}>\n        <div className="container">\n          <div className="guest-feature">\n            <div className="guest-feature__media media-frame" data-reveal-scale>\n              <div className="dissolve">\n                <img src="/images/fisayo-alonge-1.jpg" alt="Fisayo Alonge in a burgundy satin gele and beaded gown" loading="lazy" />\n                <img src="/images/fisayo-alonge-2.jpg" alt="Fisayo Alonge in a burgundy satin gele, standing portrait" loading="lazy" />\n              </div>\n            </div>\n            <div data-reveal>\n              <span className="eyebrow" style={{ color: "var(--gold-soft)" }}>Notable Work</span>\n              <h2 className="h3" style={{ marginTop: ".8rem" }}>Styled for<br />the moment.</h2>\n              <p className="body-copy" style={{ marginTop: "1.2rem" }}>Fisayo Alonge, styled by Gele Glamzzz, wearing a crown built for exactly that kind of presence.</p>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      {/* ============ Intro / Philosophy ============ */}\n      <section className="intro section-pad" id="philosophy">\n        <div className="container intro__grid intro--media-right">\n          <div className="intro__media media-frame" data-reveal-scale>\n            <div className="media-frame__art">\n              <img src="/images/intro-detail-fan.jpg" alt="Close-up detail of a hand-finished emerald green and gold gele fan fold" loading="lazy" />\n            </div>\n          </div>\n          <div className="intro__text">\n            <div className="intro__rule" data-reveal></div>\n            <h2 className="h2" data-reveal>Every fold<br />has intention.</h2>\n            <p className="body-copy" data-reveal style={{ marginTop: "1.6rem" }}>From traditional ceremonies to modern bridal moments, Gele Glamzzz transforms fabric into a statement of identity, elegance and presence. Nothing is arranged by accident. Every pleat is placed with purpose.</p>\n          </div>\n        </div>\n      </section>\n\n      {/* ============ Testimonials ============ */}\n      <section className="testimonials section-pad">\n        <div className="container container--narrow">\n          <span className="eyebrow" data-reveal style={{ color: "var(--gold-soft)" }}>Client Stories</span>\n          <span className="testimonials__mark" aria-hidden="true">&rdquo;</span>\n          <div className="testimonials__grid" style={{ marginTop: "2rem" }}>\n            <div className="testimonials__portrait media-frame media-frame--ripple" data-reveal-scale>\n              {TESTIMONIALS.map((t, i) => (\n                <div key={i} className={`media-frame__art${i === 0 ? " is-active" : ""}`} data-test-media={i}>\n                  <img src={t.img} alt={t.alt} loading="lazy" />\n                </div>\n              ))}\n            </div>\n            <div>\n              <div className="testimonial-track">\n                {TESTIMONIALS.map((t, i) => (\n                  <figure key={i} className={`testimonial${i === 0 ? " is-active" : ""}`}>\n                    <span className="testimonials__quote-mark" aria-hidden="true">&ldquo;</span>\n                    <blockquote>{t.quote}</blockquote>\n                    <div className="testimonial__meta"><span className="testimonial__meta-line"></span><cite>{t.who}</cite></div>\n                  </figure>\n                ))}\n              </div>\n              <div className="testimonials__nav">\n                <button className="testimonials__arrow" id="testimonialPrev" aria-label="Previous testimonial">←</button>\n                <span className="testimonials__count" id="testimonialCount">01 / 0{TESTIMONIALS.length}</span>\n                <button className="testimonials__arrow" id="testimonialNext" aria-label="Next testimonial">→</button>\n              </div>\n              <p className="testimonials__note">Sample content shown. Replace with real client testimonials.</p>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      {/* ============ Social Proof ============ */}\n      <section className="proof">\n        <div className="container" style={{ paddingBlock: "1.6rem 0", textAlign: "center" }}>\n          <span className="eyebrow">Trusted For</span>\n        </div>\n        <div className="proof__row">\n          <div className="proof__item"><span>Bridal</span><p className="proof__sub">Aisle to reception</p></div>\n          <div className="proof__item"><span>Occasions</span><p className="proof__sub">Birthdays &amp; milestones</p></div>\n          <div className="proof__item"><span>Editorial</span><p className="proof__sub">Campaigns &amp; shoots</p></div>\n          <div className="proof__item"><span>Private Events</span><p className="proof__sub">By invitation</p></div>\n        </div>\n      </section>\n\n      {/* ============ Journal preview ============ */}\n      <section className="journal section-pad">\n        <div className="container container--narrow">\n          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", flexWrap: "wrap", gap: "1.2rem", marginBottom: "clamp(2rem,4vw,3rem)" }}>\n            <h2 className="h2" data-reveal>From the<br />Glamzzz feed.</h2>\n            <a className="btn btn--ghost" href="/journal">See the journal <span className="btn__arrow">→</span></a>\n          </div>\n          <div className="media-gallery" data-reveal-scale>\n            {JOURNAL_MEDIA.slice(1, 4).map((m, i) => (\n              <div key={i} className="media-gallery__item">\n                <img src={m.type === "video" ? m.poster : m.src} alt={m.caption} loading="lazy" />\n                <span className="media-gallery__caption"><p>{m.sub}</p><p>{m.caption}</p></span>\n              </div>\n            ))}\n          </div>\n        </div>\n      </section>\n\n      {/* ============ Instagram ============ */}\n      <section className="instagram section-pad">\n        <div className="container">\n          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", flexWrap: "wrap", gap: "1.2rem", marginBottom: "clamp(1.6rem,3vw,2.5rem)" }}>\n            <h2 className="h2" data-reveal>Follow the<br />artistry.</h2>\n            <a className="btn btn--ghost" href="https://www.instagram.com/geleglamzzz/" target="_blank" rel="noopener noreferrer">Follow @geleglamzzz <span className="btn__arrow">→</span></a>\n          </div>\n          <div className="instagram__grid">\n            {INSTAGRAM.map((ig, i) => (\n              <a key={i} className="instagram__item" href="https://www.instagram.com/geleglamzzz/" target="_blank" rel="noopener noreferrer" data-cursor="view">\n                <div className="media-frame__art"><img src={ig.img} alt={ig.alt} loading="lazy" /></div>\n              </a>\n            ))}\n          </div>\n        </div>\n      </section>\n\n      {/* ============ Final CTA ============ */}\n      <section className="final-cta" id="finalCta">\n        <div className="final-cta__media media-frame">\n          <div className="media-frame__art"><img src="/images/story-heritage.jpg" alt="Client in a silver holographic gele and beaded pale blue gown" loading="lazy" /></div>\n        </div>\n        <div className="final-cta__scrim"></div>\n        {/* TODO(video): drop a portrait/vertical .mp4 into /public/videos/cta/ —\n            it\'s picked up automatically and will autoplay muted and looped here. */}\n        <div className="final-cta__reel">\n          <video muted loop autoPlay playsInline preload="metadata" aria-hidden="true">\n            {ctaVideo && <source src={ctaVideo.src} type={ctaVideo.type} />}\n          </video>\n        </div>\n        <div className="final-cta__content">\n          <h2 className="final-cta__headline reveal-mask">\n            <span className="line"><span>Ready</span></span>\n            <span className="line"><span>to be</span></span>\n            <span className="line"><span>crowned<span className="accent-dot">?</span></span></span>\n          </h2>\n          <a href="/booking" className="btn btn--primary" data-cursor="book">Book your experience <span className="btn__arrow">→</span></a>\n        </div>\n      </section>\n\n      <HomeScripts />\n    </>\n  );\n}\n');
write("app/classes/page.js", 'import ClassesScripts from "@/components/ClassesScripts";\n\nexport const metadata = {\n  title: "Classes: Gele Glamzzz | Learn Gele Tying in London",\n  description: "Private lessons, small group workshops and bridal party masterclasses. Learn to tie a gele with Gele Glamzzz in London.",\n};\n\nconst CLASSES = [\n  { title: "Private 1:1 Lesson", desc: "A personal session built around your own head shape, fabric and the finish you\'re trying to master. Studio or your own space.", img: "/images/classes-private-lesson.jpg" },\n  { title: "Small Group Workshop", desc: "Hands-on tying practice for small groups, friends or colleagues who want to learn together rather than one at a time.", img: "/images/classes-small-group.jpg" },\n  { title: "Bridal Party Masterclass", desc: "For the bride who wants her mothers, aunties or bridesmaids tying with confidence well before the big day arrives.", img: "/images/classes-bridal-party.jpg" },\n  { title: "Beginner\'s Foundations", desc: "Fabric, tension and structure from first principles, for anyone who has never wrapped a gele before.", img: "/images/owner-teaching.jpg" },\n];\n\nexport default function ClassesPage() {\n  return (\n    <>\n      <section className="page-hero">\n        <div className="page-hero__media">\n          <img src="/images/classes-small-group.jpg" alt="Gele tying workshop in session" loading="eager" />\n        </div>\n        <div className="page-hero__scrim" aria-hidden="true"></div>\n        <div className="page-hero__content">\n          <span className="eyebrow" data-reveal style={{ color: "var(--gold-soft)" }}>Learn The Craft</span>\n          <h1 className="display-2" data-reveal style={{ marginTop: ".6rem" }}>Tie it like<br />Gele Glamzzz.</h1>\n        </div>\n      </section>\n\n      <section className="section-pad" style={{ paddingTop: "clamp(2.5rem,5vw,4rem)" }}>\n        <div className="container container--narrow">\n          <p className="lede" data-reveal>Every gele on this site started as a lesson someone was brave enough to ask for. These sessions teach the same tension, folds and finishing used in bridal and editorial work, scaled to whatever you&apos;re learning for.</p>\n        </div>\n      </section>\n\n      <section className="section-pad" style={{ paddingTop: 0 }}>\n        <div className="container container--narrow">\n          <div className="classes__list">\n            {CLASSES.map((c, i) => (\n              <div key={i} className="classes__item">\n                <div className="classes__media media-frame" data-reveal-scale>\n                  <div className="media-frame__art"><img src={c.img} alt={c.title} loading="lazy" /></div>\n                </div>\n                <div data-reveal>\n                  <div className="classes__head">\n                    <h3 className="h3">{c.title}</h3>\n                    <span className="classes__price">Price on consultation</span>\n                  </div>\n                  <p className="body-copy">{c.desc}</p>\n                </div>\n              </div>\n            ))}\n          </div>\n          <p className="classes__note" data-reveal>Formats, group sizes and locations are flexible and confirmed at booking. Head to the booking page and select &quot;Other&quot; to start a classes enquiry.</p>\n        </div>\n      </section>\n\n      <ClassesScripts />\n    </>\n  );\n}\n');
write("lib/data.js", "export const FEATURED_WORK = [\n  { num: '01', title: 'The Bridal Crown', desc: 'A refined finishing statement for the bride who wants presence without excess.', grad: 'linear-gradient(200deg,#3a2a1c,#15100c)', line: '#caa877', sym: 'fold-a' },\n  { num: '02', title: 'The Royal Fold', desc: 'Architectural, high and unmistakably regal. Our most requested signature shape.', grad: 'linear-gradient(200deg,#5c2231,#2b2018)', line: '#d7ab6e', sym: 'fold-b' },\n  { num: '03', title: 'The Statement', desc: 'Bold volume and colour play, built for a moment that should not be missed.', grad: 'linear-gradient(200deg,#a6522e,#15100c)', line: '#f2e9d8', sym: 'fold-c' },\n  { num: '04', title: 'The Editorial', desc: 'Sculptural and campaign ready, for photography that needs to hold a frame.', grad: 'linear-gradient(200deg,#8a6b45,#2b2018)', line: '#f2e9d8', sym: 'fold-a' },\n];\n\nexport const SERVICES = [\n  { tag: 'Bridal', title: 'Bridal Gele', desc: 'For brides who want an unforgettable finishing statement.', grad: 'linear-gradient(200deg,#3a2a1c,#15100c)', line: '#caa877', sym: 'fold-a', img: '/images/hero-main.jpg' },\n  { tag: 'Heritage', title: 'Traditional Ceremonies', desc: 'Beautiful gele styling for cultural celebrations.', grad: 'linear-gradient(200deg,#5c2231,#2b2018)', line: '#d7ab6e', sym: 'fold-b', img: '/images/story-heritage.jpg' },\n  { tag: 'Celebration', title: 'Special Occasions', desc: 'Birthdays, parties and milestone moments.', grad: 'linear-gradient(200deg,#a6522e,#15100c)', line: '#f2e9d8', sym: 'fold-c', img: '/images/testimonial-portrait.jpg' },\n  { tag: 'Editorial', title: 'Photoshoots', desc: 'Editorial and creative styling built for the camera.', grad: 'linear-gradient(200deg,#8a6b45,#15100c)', line: '#f2e9d8', sym: 'fold-a', img: '/images/story-craft.jpg' },\n  { tag: 'Bespoke', title: 'Private Bookings', desc: 'Bespoke styling for private events and clients.', grad: 'linear-gradient(200deg,#2b2018,#15100c)', line: '#dac49c', sym: 'fold-b', img: '/images/intro-detail-fan.jpg' },\n];\n\nexport const PROCESS = [\n  { num: '01', title: 'Consult', body: 'We discover your vision, your event and the story you want your look to tell.' },\n  { num: '02', title: 'Prepare', body: 'We consider your outfit, event, face shape and desired aesthetic in detail.' },\n  { num: '03', title: 'Create', body: 'Your gele is carefully sculpted, folded and perfected by hand.' },\n  { num: '04', title: 'Crown', body: 'You step into your moment, ready and unforgettable.' },\n];\n\nexport const TESTIMONIALS = [\n  { quote: 'She completely transformed my look. The gele was the final piece that made everything come together.', who: 'Bridal Client, London', img: '/images/testimonial-portrait.jpg', alt: 'Client in a beaded pink gown and matching gele' },\n  { quote: 'Every fold was so precise. I felt like I was wearing a piece of art, not just fabric.', who: 'Traditional Ceremony Client', img: '/images/story-heritage.jpg', alt: 'Client in a silver holographic gele and beaded pale blue gown' },\n  { quote: 'Effortless from the first message to the final touch. I have never felt more put together.', who: 'Private Event Client, London', img: '/images/story-craft.jpg', alt: 'Client in a silver holographic gele' },\n];\n\nexport const INSTAGRAM = [\n  { img: '/images/insta-mint-veil.jpg', alt: 'Client in a mint green traditional look with matching gele and veil' },\n  { img: '/images/insta-podcast.jpg', alt: 'Gele Glamzzz styling featured on a podcast appearance' },\n  { img: '/images/insta-glam-gold.jpg', alt: 'Client in a gold and yellow patterned gele' },\n  { img: '/images/insta-mint-pose.jpg', alt: 'Client in a mint green traditional look with matching gele' },\n  { img: '/images/insta-glam-white.jpg', alt: 'Client in a white gele with beaded gold-fringe gown' },\n];\n\n/* Journal, reimagined as a pictures + video feed.\n   TODO(video): each { type:'video' } entry below has no `src` yet — drop an\n   .mp4 file into /public/videos/ and set its src (see JournalScripts.js,\n   nothing else needs to change; it autoplays muted, looped, no controls). */\nexport const JOURNAL_MEDIA = [\n  { type: 'video', src: '', poster: '/images/hero-main.jpg', caption: 'The Full Look', sub: 'Video', wide: true, suggest: 'journal-full-look.mp4' },\n  { type: 'image', src: '/images/testimonial-portrait.jpg', caption: 'The Beaded Fold', sub: 'Bridal' },\n  { type: 'image', src: '/images/story-heritage.jpg', caption: 'The Silver Fold', sub: 'Editorial' },\n  { type: 'video', src: '', poster: '/images/intro-detail-fan.jpg', caption: 'Behind the Fold', sub: 'Video', suggest: 'journal-behind-the-fold.mp4' },\n  { type: 'image', src: '/images/vogue-backstage.jpg', caption: 'Backstage, Fashion Week', sub: 'Runway' },\n  { type: 'image', src: '/images/story-craft.jpg', caption: 'Texture Study', sub: 'Detail' },\n  { type: 'video', src: '', poster: '/images/classes-small-group.jpg', caption: 'A Client Reveal', sub: 'Video', suggest: 'journal-reveal.mp4' },\n  { type: 'image', src: '/images/hero-main.jpg', caption: 'Aso-Oke Edit', sub: 'London', wide: true },\n];\n");

console.log("\nDone. Restart the dev server (Ctrl+C, then npm run dev) and check the homepage's Instagram section and the Classes page heading.");
